CREATE TYPE "status_agendamento" AS ENUM (
  'confirmado',
  'pendente',
  'cancelado',
  'remarcado',
  'finalizado'
);

CREATE TABLE "setores" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(20)
);

CREATE TABLE "fisioterapeutas" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(255) NOT NULL,
  "matricula" integer,
  "created_at" datetime,
  "updated_at" datetime
);

CREATE TABLE "agendamentos" (
  "id" integer PRIMARY KEY,
  "nome_paciente" varchar(255) NOT NULL,
  "setor_paciente" integer,
  "status" status_agendamento DEFAULT 'pendente',
  "matricula_paciente" integer,
  "dia" date,
  "horario" time,
  "created_at" datetime,
  "updated_at" datetime
);

CREATE TABLE "programacao_semanal" (
  "id" integer PRIMARY KEY,
  "dia_semana" varchar(20) NOT NULL,
  "profissional_admin" integer,
  "ativo" boolean DEFAULT true,
  "inicio_expediente" time NOT NULL,
  "fim_expediente" time NOT NULL,
  "pausa_duracao" time,
  "intervalo_minutos" integer
);

CREATE TABLE "fisioterapeuta_programacao" (
  "fisioterapeuta_id" integer,
  "programacao_semanal_id" integer,
  "ativo" boolean DEFAULT true
);

CREATE TABLE "historico_agendamentos" (
  "id" integer PRIMARY KEY,
  "agendamento_id" integer,
  "fisioterapeuta_id" integer
);

ALTER TABLE "agendamentos" ADD FOREIGN KEY ("setor_paciente") REFERENCES "setores" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "programacao_semanal" ADD FOREIGN KEY ("profissional_admin") REFERENCES "fisioterapeutas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "fisioterapeuta_programacao" ADD FOREIGN KEY ("fisioterapeuta_id") REFERENCES "fisioterapeutas" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "fisioterapeuta_programacao" ADD FOREIGN KEY ("programacao_semanal_id") REFERENCES "programacao_semanal" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "historico_agendamentos" ADD FOREIGN KEY ("agendamento_id") REFERENCES "agendamentos" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "historico_agendamentos" ADD FOREIGN KEY ("fisioterapeuta_id") REFERENCES "fisioterapeutas" ("id") DEFERRABLE INITIALLY IMMEDIATE;
